<?php $layout='layouts.app'; $name=trim($student['first_name'].' '.($student['middle_name']??'').' '.$student['last_name']); $a=$attendance; $total=(int)($a['total']??0); $rate=$total>0?round(((int)($a['present']??0)/$total)*100,1):0; ?>
<div style="display:flex;justify-content:space-between;align-items:center"><div><h1><?= e($name) ?></h1><p class="muted"><?= e($student['admission_no']) ?> · <?= e($student['class_name']??'Unassigned') ?><?= !empty($student['stream_name'])?' · '.e($student['stream_name']):'' ?></p></div><a class="btn btn-outline" href="/parent-portal">Back to portal</a></div>
<div class="grid grid-4" style="margin-top:var(--space-4)"><div class="card"><div class="card-body"><div class="muted">Attendance</div><h2><?= e((string)$rate) ?>%</h2><small><?= (int)($a['present']??0) ?> present · <?= (int)($a['absent']??0) ?> absent</small></div></div><div class="card"><div class="card-body"><div class="muted">Outstanding fees</div><h2>KES <?= number_format(array_sum(array_map(static fn($i)=>(float)$i['balance'],$invoices)),2) ?></h2></div></div><div class="card"><div class="card-body"><div class="muted">Published report cards</div><h2><?= count($report_cards) ?></h2></div></div><div class="card"><div class="card-body"><div class="muted">Class</div><h2><?= e($student['class_name']??'—') ?></h2></div></div></div>
<div class="grid grid-2" style="margin-top:var(--space-4)"><div class="card"><div class="card-body"><h2>Report cards</h2><table class="table"><thead><tr><th>Examination</th><th>Term</th><th>Percentage</th><th>Grade</th></tr></thead><tbody><?php foreach($report_cards as $card): ?><tr><td><?= e($card['examination_name']) ?></td><td><?= e($card['term_name']) ?></td><td><?= e((string)$card['percentage']) ?>%</td><td><?= e((string)$card['grade']) ?></td></tr><?php endforeach; if(!$report_cards): ?><tr><td colspan="4">No published report cards.</td></tr><?php endif; ?></tbody></table></div></div>
<div class="card"><div class="card-body"><h2>Fees</h2><table class="table"><thead><tr><th>Invoice</th><th>Date</th><th>Status</th><th>Balance</th></tr></thead><tbody><?php foreach($invoices as $invoice): ?><tr><td><?= e($invoice['invoice_no']) ?></td><td><?= e($invoice['invoice_date']) ?></td><td><?= e(ucfirst($invoice['status'])) ?></td><td>KES <?= number_format((float)$invoice['balance'],2) ?></td></tr><?php endforeach; if(!$invoices): ?><tr><td colspan="4">No issued invoices.</td></tr><?php endif; ?></tbody></table></div></div></div>
<div class="card" style="margin-top:var(--space-4)"><div class="card-body"><h2>Weekly timetable</h2><table class="table"><thead><tr><th>Day</th><th>Period</th><th>Subject</th><th>Teacher</th></tr></thead><tbody><?php foreach($timetable as $entry): ?><tr><td><?= e(['','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'][(int)$entry['day_of_week']]??(string)$entry['day_of_week']) ?></td><td><?= e($entry['period_name']) ?> <?= !empty($entry['starts_at'])?'('.e($entry['starts_at']).'–'.e($entry['ends_at']).')':'' ?></td><td><?= e($entry['subject_name']??ucfirst($entry['entry_type'])) ?></td><td><?= e($entry['teacher_name']??'') ?></td></tr><?php endforeach; if(!$timetable): ?><tr><td colspan="4">No published timetable is available for this class.</td></tr><?php endif; ?></tbody></table></div></div>
<div class="card" style="margin-top:var(--space-4)"><div class="card-body"><h2>Recent attendance</h2><table class="table"><thead><tr><th>Date</th><th>Status</th><th>Remarks</th></tr></thead><tbody><?php foreach($attendance_history as $row): ?><tr><td><?= e($row['attendance_date']) ?></td><td><?= e(ucfirst($row['status'])) ?></td><td><?= e((string)($row['remarks']??'')) ?></td></tr><?php endforeach; if(!$attendance_history): ?><tr><td colspan="3">No attendance records.</td></tr><?php endif; ?></tbody></table></div></div>
